local config = {
  ui_story_32250401_1_dialog_content = "Tiare!",
  ui_story_32250401_2_dialog_content = "A-Apa yang terjadi? Apakah semua orang baik-baik saja? Di mana mayat-mayatnya?",
  ui_story_32250401_3_dialog_content = "Mereka mati... Mereka semua mati.",
  ui_story_32250401_4_dialog_content = "Semua mati?",
  ui_story_32250401_5_dialog_content = "Itu tidak mungkin! Bagaimana dengan Vice dan Carleen? Bagaimana Eclipsites bisa berhasil masuk?",
  ui_story_32250401_6_dialog_content = "Vice dan Carleen? Eclipsite?",
  ui_story_32250401_7_dialog_content = "Apa yang kamu bicarakan, PlayerName? Karena aku sedang membicarakan tentang pemburu liar.",
  ui_story_32250401_8_dialog_content = "P-Pemburu gelap?",
  ui_story_32250401_9_dialog_content = "Ya. Sebuah kelompok pemburu liar baru-baru ini muncul di hutan, menjebak dan membunuh apa saja yang bisa mereka tangkap...",
  ui_story_32250401_10_dialog_content = "Lebih dari seratus hewan dibantai minggu lalu, dan pagi ini tetua menemukan lebih banyak lagi mayat...",
  ui_story_32250401_11_dialog_content = "Jadi, tubuh yang kamu sebutkan adalah tubuh hewan?",
  ui_story_32250401_12_dialog_content = "Jangan tampak begitu lega. Ini masih merupakan masalah yang sangat serius.",
  ui_story_32250401_13_dialog_content = "Biar kujelaskan.",
  ui_story_32250401_14_dialog_content = "Tua! Saya tidak menyadari bahwa Anda juga di sini!",
  ui_story_32250401_15_dialog_content = "Para pemburu ini tidak merasa hormat atau terima kasih terhadap alam.",
  ui_story_32250401_16_dialog_content = "Perburuan mereka tidak lebih dari didorong oleh harga pasar dari mangsa mereka...",
  ui_story_32250401_17_dialog_content = "Mereka merampas bagian paling berharga dari hewan-hewan itu dan meninggalkan sisanya membusuk. Apa yang bisa memberi makan banyak makhluk hidup sekarang terbuang sia-sia dengan cara yang paling menyedihkan.",
  ui_story_32250401_18_dialog_content = "Jika dibiarkan, para pemburu ini akan mengganggu keseimbangan alam hutan. Mereka harus dihentikan!",
  ui_story_32250401_19_dialog_content = "Begitu... Maaf telah meremehkan betapa seriusnya situasi ini. Aku belum pernah berurusan dengan hal seperti ini sebelumnya.",
  ui_story_32250401_20_dialog_content = "Apakah kita tahu hal lain tentang para pemburu ini?",
  ui_story_32250401_21_dialog_content = "Rubah-rubahku dan aku menyelinap ke kamp mereka sebelumnya, dan kami menemukan kotak korek api ini.",
  ui_story_32250401_22_dialog_content = "Emblem ini...",
  ui_story_32250401_23_dialog_content = "Aku pernah melihatnya sebelumnya! Aku pikir itu milik sebuah bar di Umbraton.",
  ui_story_32250401_24_dialog_content = "Maafkan saya, kalian berdua.",
  ui_story_32250401_25_dialog_content = "Saya tidak percaya saya pernah melihat wajah kalian di sini sebelumnya. Maafkan saya, tapi apakah ini pertama kalinya kalian di sini?",
  ui_story_32250401_26_dialog_content = "Tentu saja ini pertama kalinya! Kamu tidak akan berdiri di sana jika bukan—",
  ui_story_32250401_27_dialog_content = "E-Ehem!",
  ui_story_32250401_28_dialog_content = "T-Tolong maafkan ketidak sopanan kami dan izinkan saya menjelaskan, tuan. Ibu saya sangat sakit, dan seorang dokter di Longzhou mengatakan kepada kami bahwa hanya empedu beruang yang bisa menyembuhkan penyakitnya.",
  ui_story_32250401_29_dialog_content = "Kami tidak tahu harus mencari di mana untuk hal seperti itu, jadi kami mulai bertanya ke seluruh Umbraton. Untungnya, kami bertemu dengan seorang pemilik bar yang baik hati...",
  ui_story_32250401_30_dialog_content = "Dan pemilik bar memberi tahu kami bahwa kita mungkin bisa membeli beberapa di bar tertentu.",
  ui_story_32250401_31_dialog_content = "Yang ini di sini, lihat?",
  ui_story_32250401_32_dialog_content = "Begitu ya... Ya, kebetulan saya cukup sering mengunjungi bar itu.",
  ui_story_32250401_33_dialog_content = "\"Malam ketika bintang-bintang jatuh di atas menara.\"",
  ui_story_32250401_34_dialog_content = "Hah? Oh, uh... \"Ular bergerak di dalam jurang.\"",
  ui_story_32250401_35_dialog_content = "Hahaha! Selamat datang, pelanggan yang terhormat! Silakan, masuklah!",
  ui_story_32250401_36_dialog_content = "Mengenai efek obat, empedu beruang yang paling kuat adalah jenis emas, yang hanya diproduksi oleh beruang betina setelah melahirkan tetapi sebelum memasuki masa hibernasi.",
  ui_story_32250401_37_dialog_content = "Beruntung bagi Anda, toko kami baru saja menerima pengiriman langsung dari Northland.",
  ui_story_32250401_38_dialog_content = "Anda-",
  ui_story_32250401_39_dialog_content = "I-Itu luar biasa! Tapi hanya karena penasaran, apa yang terjadi pada anak beruang setelah Anda membunuh induk beruang?",
  ui_story_32250401_40_dialog_content = "Heheh... Tidak perlu khawatir, temanku. Para penikmat makanan di Astra selalu memiliki tempat di meja mereka untuk anak beruang.",
  ui_story_32250401_41_dialog_content = "!",
  ui_story_32250401_42_dialog_content = "Hei! Ada orang di belakang sana? Berapa lama lagi saya harus menunggu pesanan dua ratus lidah burung gereja hitam saya?",
  ui_story_32250401_43_dialog_content = "Oh ya, itu salah satu pelanggan terbaik kami. Mohon maaf sebentar, kalian berdua—",
  ui_story_32250401_44_dialog_content = "Mengapa kamu menghentikanku, PlayerName? Bukankah dia pemimpin para pemburu liar?",
  ui_story_32250401_45_dialog_content = "Menghilangkan pemimpin tidak akan menyelesaikan apa pun, karena mereka bisa saja menunjuk yang baru. Kita perlu tetap tenang dan memikirkan solusi yang lebih menyeluruh.",
  ui_story_32250401_46_dialog_content = "Tapi melindungi hutan adalah tugasku...",
  ui_story_32250401_47_dialog_content = "Setelah melihat apa yang mereka lakukan pada hewan-hewan itu, saya tidak bisa tidak merasa marah.",
  ui_story_32250401_48_dialog_content = "Tak bisa percaya aku baru saja membiarkan mereka pergi begitu mudah...",
  ui_story_32250401_49_option_content = "Kita tidak akan membiarkan mereka pergi.",
  ui_story_32250401_50_dialog_content = "Kita sedang bersabar dan menunggu waktu yang tepat untuk menyerang. Itu adalah hal yang cerdas untuk dilakukan, Tiare.",
  ui_story_32250401_51_dialog_content = "Jika kita bekerja sama, saya yakin kita bisa mengalahkan mereka semua satu per satu!",
  ui_story_32250401_52_option_content = "Kamu sudah melakukan begitu banyak.",
  ui_story_32250401_53_dialog_content = "Apakah itu penyamaran, pelacakan, atau bahkan berburu, semua kekuatanmu telah sangat membantu sejauh ini.",
  ui_story_32250401_54_dialog_content = "Kami tidak akan pernah menemukan bar itu jika kamu tidak menyusup ke kamp mereka dan menemukan kotak korek ini.",
  ui_story_32250401_55_dialog_content = "Dan dengan menguping di bar, Anda bahkan menemukan lokasi pemimpin mereka dan kata sandi rahasia mereka.",
  ui_story_32250401_56_dialog_content = "Tak satu pun dari ini akan mungkin tanpa dirimu!",
  ui_story_32250401_57_dialog_content = "Kamu membuatnya terdengar seolah-olah saya telah melakukan sesuatu yang luar biasa.",
  ui_story_32250401_58_dialog_content = "Jadi apa sebenarnya yang Anda maksud dengan \"solusi yang lebih menyeluruh\"?",
  ui_story_32250401_59_dialog_content = "Apakah kamu akan melaporkan mereka ke orang-orang \"polisi\" itu?",
  ui_story_32250401_60_dialog_content = "Sayangnya, dengan begitu banyak organisasi berbeda yang mengendalikan jalanan Umbraton, kita tidak bisa sepenuhnya mengandalkan polisi.",
  ui_story_32250401_61_dialog_content = "Tapi kita bisa membicarakannya dengan salah satu organisasi tersebut.",
  ui_story_32250401_62_dialog_content = "Bos! Sebuah surat tiba-tiba muncul di gerbang barusan...",
  ui_story_32250401_63_dialog_content = "Apa maksudmu, \"muncul tiba-tiba\"?",
  ui_story_32250401_64_dialog_content = "Yah, tidak ada yang bisa melihat dengan jelas siapa yang menitipkannya...",
  ui_story_32250401_65_dialog_content = "Humph, dasar orang-orang bodoh yang tidak berguna. Serahkan di sini!",
  ui_story_32250401_66_dialog_content = "Siap, Pak!",
  ui_story_32250401_67_dialog_content = "... Tidak bisa dipercaya!",
  ui_story_32250401_68_dialog_content = "A-Apa masalahnya, bos?",
  ui_story_32250401_69_dialog_content = "... Itu sebuah peringatan.",
  ui_story_32250401_70_dialog_content = "Menurut ini, ada orang yang memperhatikan betapa suksesnya gelanggang pertarungan bawah tanah kita, dan sekarang mereka ingin ikut serta dalam aksi tersebut.",
  ui_story_32250401_71_dialog_content = "Dikatakan mereka sedang merencanakan semacam arena pertarungan binatang!",
  ui_story_32250401_72_dialog_content = "Orang melawan binatang, huh? Itu bukan ide yang buruk!",
  ui_story_32250401_73_dialog_content = "Apa, gila? Jika mereka berhasil melakukan ini, bisnis kita sama saja dengan mati!",
  ui_story_32250401_74_dialog_content = "Y-Ya, kamu benar... Ini benar-benar parah, bos!",
  ui_story_32250401_75_dialog_content = "Namun, masih ada kemungkinan surat ini hanya omong kosong belaka... Ini kan Umbraton, bukan?",
  ui_story_32250401_76_dialog_content = "Aku tahu itu, dasar idiot! Sepertinya aku harus memeriksa sendiri.",
  ui_story_32250401_77_dialog_content = "Apakah ini basis operasi mereka?",
  ui_story_32250401_78_dialog_content = "Ya, tetua. Saya telah melacak pemimpin mereka sampai ke tempat ini.",
  ui_story_32250401_79_dialog_content = "Dia tidak menyadari bahwa dia sedang diikuti, dan memerintahkan anak buahnya untuk membongkar beberapa perangkap dan busur silang.",
  ui_story_32250401_80_dialog_content = "Beberapa jebakan itu masih berlumuran darah!",
  ui_story_32250401_81_dialog_content = "Mudah, Tiare. Kita sudah memiliki semua kekuatan yang kita butuhkan sekarang, jadi cukup ikuti rencana dan kita akan menang.",
  ui_story_32250401_82_dialog_content = "<color=#e8d9bb>Auuu—</color>",
  ui_story_32250401_83_dialog_content = "Rubah-rubah, jawab panggilanku—",
  ui_story_32250401_84_dialog_content = "<color=#e8d9bb>Suara peluit tajam menembus udara saat tak terhitung jumlah rubah artik beraksi, berlari ke setiap sudut rumah besar.</color>",
  ui_story_32250401_85_dialog_content = "(Luar biasa... Tiare benar-benar bisa berbagi kehendaknya dengan setiap rubah artik!)",
  ui_story_32250401_86_dialog_content = "(Inikah kekuatan pemimpin suku Arctic Fox?)",
  ui_story_32250401_87_dialog_content = "Aku akan membantu juga!",
  ui_story_32250401_88_dialog_content = "<color=#e8d9bb>Setelah banyak keributan, seekor rubah berteriak dari suatu tempat di belakang rumah besar.</color>",
  ui_story_32250401_89_dialog_content = "Kayu bakar sudah ditempatkan dan telah disiram dengan minyak, begitu juga dengan ruangan yang menyimpan jebakan dan busur panah mereka. Begitu api dinyalakan, tidak akan ada yang tersisa.",
  ui_story_32250401_90_dialog_content = "Kamu mendapatkan semua itu dari satu raungan saja? Apakah kamu yakin kamu mengerti semuanya?",
  ui_story_32250401_91_dialog_content = "Aku bisa memahamimu dengan sangat baik, 'kan?",
  ui_story_32250401_92_dialog_content = "Tentu saja boleh!",
  ui_story_32250401_93_dialog_content = "Jadi, kenapa repot-repot bertanya itu padaku?",
  ui_story_32250401_94_dialog_content = "Uh... Tidak apa-apa. Nyalakan apinya!",
  ui_story_32250401_95_dialog_content = "<color=#e8d9bb>Tiare memberikan suara siulan tajam dan tinggi lagi.</color>",
  ui_story_32250401_96_dialog_content = "Siapa di luar sana?",
  ui_story_32250401_97_dialog_content = "Ahh! Api! Api!",
  ui_story_32250401_98_dialog_content = "... Masuk ke sana dan ambil sebanyak mungkin busur silang yang bisa kamu ambil!",
  ui_story_32250401_99_dialog_content = "Siap, Pak!",
  ui_story_32250401_100_dialog_content = "Anda tidak akan kemana-mana!",
  ui_story_32250401_101_dialog_content = "Urgh—",
  ui_story_32250401_102_dialog_content = "Aaaaaahhh—",
  ui_story_32250401_103_dialog_content = "F-Fox? Apa yang mereka lakukan di sini—",
  ui_story_32250401_104_dialog_content = "Sepertinya kamu masih harus banyak belajar!",
  ui_story_32250401_105_dialog_content = "<color=#e8d9bb>Auuu—</color>",
  ui_story_32250401_106_dialog_content = "Argh... M-Mundur, kalian binatang!",
  ui_story_32250401_107_dialog_content = "(Kebanyakan dari mereka seharusnya sudah ada di sini sekarang... Sepertinya ini adalah kesempatan kita...)",
  ui_story_32250401_108_dialog_content = "Saatnya bagi kita untuk mundur, Tiare!",
  ui_story_32250401_109_dialog_content = "Baiklah!",
  ui_story_32250401_110_dialog_content = "Hei! Aku bilang \"mundur,\" bukan \"angkat aku\"!",
  ui_story_32250401_111_dialog_content = "Jangan khawatir, kamu sangat ringan!",
  ui_story_32250401_112_dialog_content = "Aaaaaahhh—",
  ui_story_32250401_113_dialog_content = "Tolong! Kasihanilah!",
  ui_story_32250401_114_dialog_content = "Apa yang kamu tahu tentang belas kasihan? Berapa kali kamu dan pasukanmu mengabaikan jeritan makhluk hutan kita saat kalian membantai mereka?",
  ui_story_32250401_115_dialog_content = "Ah! Dia berbicara! Rubah itu berbicara!",
  ui_story_32250401_116_dialog_content = "Apa sih yang kamu bicarakan?",
  ui_story_32250401_117_dialog_content = "Itu dia tepat di sana, Bos!",
  ui_story_32250401_118_dialog_content = "Siapa kalian? T-Tidak apa-apa... Tolong, kamu harus menyelamatkan kami! Rubah-rubah ini telah menjadi gila!",
  ui_story_32250401_119_dialog_content = "Kamu bercanda, kan? Kamulah yang menangkap mereka untuk arena kecilmu, bukan? Siapa lagi yang seharusnya mereka serang, huh?",
  ui_story_32250401_120_dialog_content = "A-Arena? Apa gerangan yang kamu bicarakan?",
  ui_story_32250401_121_dialog_content = "Saya memiliki keraguan ketika membaca surat itu...",
  ui_story_32250401_122_dialog_content = "Tapi sekarang setelah aku melihat rubah-rubahmu, aku tahu pasti bahwa kau mencoba menginvasi wilayahku!",
  ui_story_32250401_123_dialog_content = "A-Aku tidak tahu apa yang kamu bicarakan! Rubah-rubah ini baru saja muncul beberapa menit yang lalu, aku bersumpah!",
  ui_story_32250401_124_dialog_content = "Cobaan bagus, teman, tapi kita berada di Umbraton. Jika kamu tidak membawa mereka ke sini dari Northland, bagaimana mereka bisa sampai di sini?",
  ui_story_32250401_125_dialog_content = "Tunggu... Saya baru ingat! Mereka dikendalikan oleh seorang wanita dan pemuda! Mereka ada di toko saya sebelumnya!",
  ui_story_32250401_126_dialog_content = "Oh ya? Jadi, di mana mereka?",
  ui_story_32250401_127_dialog_content = "A-Aku tidak yakin, tapi apakah kamu melihat rubah itu? Dia lebih besar dari yang lain, dan aku yakin dia bekerja untuk mereka! Dia bahkan bisa berbicara!",
  ui_story_32250401_128_dialog_content = "Awooo! Mengaum—",
  ui_story_32250401_129_dialog_content = "Anda menyebut itu \"berbicara\"?",
  ui_story_32250401_130_dialog_content = "Ini hanya pura-pura!",
  ui_story_32250401_131_dialog_content = "Kamu satu-satunya yang berpura-pura di sini, bajingan! Aku akan mengajarimu untuk bermain-main dengan saya di wilayahku sendiri!",
  ui_story_32250401_132_dialog_content = "Baiklah, kawan-kawan! Usir penjahat-penjahat ini dari pandanganku, tapi sebelumnya hajar mereka dengan keras!",
  ui_story_32250401_133_dialog_content = "Tangkap mereka—",
  ui_story_32250401_134_dialog_content = "Aaaaaahhhh—",
  ui_story_32250401_135_dialog_content = "... Dan begitulah kami memberikan pukulan penyelesaian kepada para pemburu itu. Setelah itu, mereka tidak pernah menginjakkan kaki di hutan kami lagi, dan perdamaian akhirnya kembali ke rumah kami.",
  ui_story_32250401_136_dialog_content = "Luar biasa!",
  ui_story_32250401_137_dialog_content = "Kamu luar biasa, Tiare! Teman Caelestite-mu terdengar sangat pintar juga!",
  ui_story_32250401_138_dialog_content = "Heehee... Tentu saja dia! Dia kebetulan adalah orang paling pintar yang aku kenal!",
  ui_story_32250401_139_dialog_content = "(Itu dia lagi menceritakan cerita itu... Sedikit terlalu memalukan untuk pergi ke sana sekarang, jadi aku akan menunggu saja.)",
  ui_story_32250401_140_dialog_content = "Hei, lihat! Itu Caelestite yang super pintar!",
  ui_story_32250401_141_dialog_content = "Kenapa kamu hanya berdiri di sana saja, PlayerName? Kemarilah!",
  ui_story_32250401_142_dialog_content = "Tuan Novio mengatakan akan ada aurora malam ini, dan saya ingin membawa Anda ke tempat terbaik untuk melihatnya!",
  ui_story_32250401_143_dialog_content = "Tunggu! Kau tidak akan menjemputku lagi, 'kan?",
  ui_story_32250401_144_dialog_content = "Baiklah! Ayo pergi sekarang!",
  ui_story_32250401_145_dialog_content = "Ahhhhh—"
}
return config
